const DollV17={
 data:DollV17Data,
 label:{hair:'发型',face:'表情',dress:'连衣裙',set:'套装',top:'上衣',outer:'外套',bottom:'下装',shorts:'短裤',socks:'袜子',shoes:'鞋子',headwear:'发饰',hat:'帽子',headphones:'耳机',glasses:'眼镜',earrings:'耳饰',bag:'包包',plush:'玩偶',other:'其他配饰',small:'小配件'},
 order:{female:['dress','top','outer','bottom','socks','shoes','headwear','headphones','glasses','earrings','bag','plush','other'],male:['set','top','outer','bottom','shorts','socks','shoes','hat','headphones','glasses','earrings','bag','small']},
 starter:{female:{top:0,bottom:0,shoes:0},male:{top:0,bottom:0,shoes:0}},
 cats(g){return this.data.genders[g].cats},
 genderOf(id){const a=living.avatars[id]||{};if(a.doll?.gender)return a.doll.gender;if(a.mix&&[0,1].includes(a.mix.body))return a.mix.body===0?'male':'female';return a.cut==='suit'||id!=='me'&&roles.findIndex(r=>r.id===id)%2===1?'male':'female'},
 fresh(g){return {v:17,gender:g,hair:g==='female'?4:0,face:0,eye:0,skin:1,items:{...this.starter[g]}}},
 defaults(id){const a=living.avatars[id]||{};return this.valid(a.doll)?structuredClone(a.doll):this.fresh(this.genderOf(id))},
 valid(d){if(!d||d.v!==17||!this.data.genders[d?.gender]||typeof d.items!=='object'||!d.items)return false;const c=this.cats(d.gender),ok=(cat,i)=>Number.isInteger(i)&&i>=0&&i<c[cat].length;if(!ok('hair',d.hair)||!ok('face',d.face)||!Number.isInteger(d.eye)||d.eye<0||d.eye>=this.data.eyes.length||!Number.isInteger(d.skin)||d.skin<0||d.skin>=this.data.skins.length)return false;return Object.entries(d.items).every(([cat,i])=>this.order[d.gender].includes(cat)&&ok(cat,i))},
 // 连衣裙/套装替代上下装；男生下装与短裤二选一
 pick(d,cat,i){const items={...d.items};if(i<0)delete items[cat];else{items[cat]=i;if(cat==='dress'||cat==='set'){delete items.top;delete items.bottom;delete items.shorts}if(['top','bottom','shorts'].includes(cat)){delete items.dress;delete items.set}if(cat==='bottom')delete items.shorts;if(cat==='shorts')delete items.bottom}return {...d,items}},
 sprite([sx,sy,sw,sh],[x,y,w,h],filter=''){const [W,H]=this.data.size,s=`<svg x="${x}" y="${y}" width="${w}" height="${h}" viewBox="${sx} ${sy} ${sw} ${sh}" preserveAspectRatio="none"><image href="${this.data.atlas}" width="${W}" height="${H}"/></svg>`;return filter?`<g filter="url(#${filter})">${s}</g>`:s},
 matrix(rgb,base){return rgb.map((v,i)=>[0,1,2].map(j=>j===i?(v/base[i]).toFixed(3):0).concat([0,0]).join(' ')).join(' ')+' 0 0 0 1 0'},
 eyeMatrix(rgb){const k=rgb.map(v=>v/128);return k.map(c=>`${(.3*c).toFixed(3)} ${(.59*c).toFixed(3)} ${(.11*c).toFixed(3)} 0 0`).join(' ')+' 0 0 0 1 0'},
 render(d,label='自由搭配的Q版形象'){const G=this.data.genders[d.gender],c=G.cats,u='d'+crypto.randomUUID().replace(/-/g,''),[bx,by,bw,bh]=G.box,parts=[{...G.body,z:1},{...G.skin,z:2,skin:1}];
  const add=(cat,i)=>{const e=c[cat]?.[i];if(!e)return;for(const p of e.parts)parts.push({...p,z:cat==='shoes'&&d.items.set!=null?6.5:p.z})};
  add('hair',d.hair);add('face',d.face);for(const [cat,i] of Object.entries(d.items))add(cat,i);
  const body=parts.filter(p=>!(p.iris&&d.eye===0)).sort((a,b)=>a.z-b.z).map(p=>this.sprite(p.s,p.d,p.skin?u+'s':p.iris?u+'e':'')).join(''),leg=G.crotch-by,cx=G.cx-bx;
  return `<span class="chibi doll17" role="img" aria-label="${escapeHtml(label)}"><svg viewBox="0 0 ${bw} ${bh}" preserveAspectRatio="xMidYMax meet"><defs><filter id="${u}s" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values="${this.matrix(this.data.skins[d.skin],G.skin.base)}"/></filter><filter id="${u}e" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values="${this.eyeMatrix(this.data.eyes[d.eye])}"/></filter><clipPath id="${u}t"><rect width="${bw}" height="${leg}"/></clipPath><clipPath id="${u}l"><rect y="${leg}" width="${cx}" height="${bh-leg}"/></clipPath><clipPath id="${u}r"><rect x="${cx}" y="${leg}" width="${bw-cx}" height="${bh-leg}"/></clipPath><g id="${u}"><g transform="translate(${-bx} ${-by})">${body}</g></g></defs><use href="#${u}" clip-path="url(#${u}t)"/><g class="doll-leg-left" style="transform-origin:${cx-14}px ${leg}px"><use href="#${u}" clip-path="url(#${u}l)"/></g><g class="doll-leg-right" style="transform-origin:${cx+14}px ${leg}px"><use href="#${u}" clip-path="url(#${u}r)"/></g></svg></span>`},
 thumb(p){const [,,sw,sh]=p.s,k=Math.min(52/sw,52/sh),w=sw*k,h=sh*k;return `<svg class="doll17-thumb" viewBox="0 0 56 56">${this.sprite(p.s,[(56-w)/2,(56-h)/2,w,h])}</svg>`},
 key(g,cat,i){return `${g[0]}.${cat}.${i}`},
 catalog(){const out={};for(const [g,G] of Object.entries(this.data.genders))for(const [cat,list] of Object.entries(G.cats))list.forEach((e,i)=>{if(e.price!=null)out[this.key(g,cat,i)]={name:e.name,price:e.price}});return out},
 unpaid(d){const cat=this.catalog();return Object.entries(d.items).map(([c,i])=>this.key(d.gender,c,i)).filter(k=>cat[k]?.price>0&&!homeland.owned.includes(k))}
};
const priorDollAvatar=chibiAvatar;
chibiAvatar=function(id='me',draft=null){if(draft?.v===17)return DollV17.render(draft);if(draft)return priorDollAvatar(id,draft);const uploaded=mediaCache.get('chibi:'+id);if(uploaded)return `<span class="chibi"><img src="${uploaded}" alt="自定义Q版形象"></span>`;return DollV17.render(DollV17.defaults(id),(id==='me'?profile.name:roles.find(r=>r.id===id)?.name||'角色')+'的Q版形象')};
openChibiEditor=function(id='me'){let d=DollV17.defaults(id),open='hair';const who=id==='me'?'我':escapeHtml(roles.find(r=>r.id===id)?.name||'角色');
 const draw=()=>{const dlg=$('#utilityDialog'),keep=dlg.open?dlg.scrollTop:0,G=DollV17.data.genders[d.gender],c=G.cats,cat=DollV17.catalog(),due=DollV17.unpaid(d),cost=due.reduce((n,k)=>n+cat[k].price,0);
  const grid=(name)=>{const list=c[name],cur=name==='hair'||name==='face'?d[name]:d.items[name]??-1,optional=!(name==='hair'||name==='face');return `<div class="doll17-grid">${optional?`<button data-doll-cat="${name}" data-doll-i="-1" aria-pressed="${cur<0}"><span class="doll17-none">不${['bag','plush','other','small'].includes(name)?'带':['headwear','hat','headphones','glasses','earrings'].includes(name)?'戴':'穿'}</span><small>无</small></button>`:''}${list.map((e,i)=>{const p=e.parts.find(x=>x.z===13||x.z===9)||e.parts[0],k=DollV17.key(d.gender,name,i),own=e.price==null||e.price===0||homeland.owned.includes(k);return `<button data-doll-cat="${name}" data-doll-i="${i}" aria-pressed="${cur===i}">${DollV17.thumb(p)}<small>${escapeHtml(e.name)}</small>${own?'':`<em>¥${e.price}</em>`}</button>`}).join('')}</div>`};
  const tabs=['hair','face','look',...DollV17.order[d.gender]].filter(t=>t==='look'||c[t]);
  const body=open==='look'?`<h3>瞳色</h3><div class="doll17-swatches">${DollV17.data.eyes.map((rgb,i)=>`<button data-doll-eye="${i}" aria-pressed="${d.eye===i}" style="--sw:rgb(${rgb})" aria-label="瞳色 ${i+1}"></button>`).join('')}</div><h3>肤色</h3><div class="doll17-swatches">${DollV17.data.skins.map((rgb,i)=>`<button data-doll-skin="${i}" aria-pressed="${d.skin===i}" style="--sw:rgb(${rgb})" aria-label="肤色 ${i+1}"></button>`).join('')}</div>`:grid(open);
  const p=homePanel(`<div class="eyebrow">LITTLE WARDROBE</div><h2>${who} · 换装</h2><div class="living-preview doll17-stage" id="chibiLive">${DollV17.render(d)}</div><div class="doll17-gender"><button data-doll-gender="female" aria-pressed="${d.gender==='female'}">女生</button><button data-doll-gender="male" aria-pressed="${d.gender==='male'}">男生</button></div><p class="daily-caption">${d.gender==='female'?'女生':'男生'}衣柜只显示${d.gender==='female'?'女生':'男生'}的发型、衣服和配饰。连衣裙/套装会替代上衣和下装；试穿免费，保存时才购买未拥有的单品。</p><nav class="doll17-tabs">${tabs.map(t=>`<button data-doll-tab="${t}" aria-pressed="${open===t}">${t==='look'?'瞳色肤色':DollV17.label[t]}</button>`).join('')}</nav>${body}<p class="daily-caption">零钱 ¥${PalaisWallet.money(wallet.balance)}${cost?` · 需购买 ${due.length} 件，共 ¥${cost}`:' · 当前搭配无需付费'}</p><div class="actions"><button class="secondary" id="uploadLayeredFigure">上传完整形象</button><button class="primary" id="saveDoll17">${cost?`购买并保存 · ¥${cost}`:'保存搭配'}</button></div><input type="file" hidden id="layeredFigureFile" accept="image/png,image/jpeg,image/webp">`);
  p.scrollTop=keep;
  p.querySelectorAll('[data-doll-tab]').forEach(b=>b.onclick=()=>{open=b.dataset.dollTab;draw()});
  p.querySelectorAll('[data-doll-gender]').forEach(b=>b.onclick=()=>{if(b.dataset.dollGender!==d.gender){d=DollV17.fresh(b.dataset.dollGender);open='hair';draw()}});
  p.querySelectorAll('[data-doll-cat]').forEach(b=>b.onclick=()=>{const k=b.dataset.dollCat,i=Number(b.dataset.dollI);d=k==='hair'||k==='face'?{...d,[k]:i}:DollV17.pick(d,k,i);draw()});
  p.querySelectorAll('[data-doll-eye]').forEach(b=>b.onclick=()=>{d={...d,eye:Number(b.dataset.dollEye)};draw()});
  p.querySelectorAll('[data-doll-skin]').forEach(b=>b.onclick=()=>{d={...d,skin:Number(b.dataset.dollSkin)};draw()});
  $('#uploadLayeredFigure').onclick=()=>$('#layeredFigureFile').click();
  $('#layeredFigureFile').onchange=async e=>{try{await mediaWrite('chibi:'+id,await prepareImage(e.target.files[0],1000));p.close();renderHomeland();toast('完整形象已上传')}catch(err){toast(err.message)}};
  $('#saveDoll17').onclick=async()=>{const b=$('#saveDoll17');b.disabled=true;try{if(!DollV17.valid(d))throw Error('请选择有效的搭配');let w=wallet,h=homeland;for(const k of DollV17.unpaid(d)){const r=PalaisHomeCash.purchaseStyle(w,h,k,crypto.randomUUID(),Date.now(),cat);w=r.wallet;h=r.home}const old=mediaCache.get('chibi:'+id)||null;await mediaWrite('chibi:'+id,null);try{livingCommit(w,{...living,avatars:{...living.avatars,[id]:{...living.avatars[id],layered:false,doll:structuredClone(d)}}},h)}catch(err){await mediaWrite('chibi:'+id,old).catch(()=>{});throw err}p.close();renderHomeland();toast(cost?`已购买 ${due.length} 件单品并保存搭配`:'搭配已保存')}catch(err){toast(err.message);b.disabled=false}};
 };draw()};
